    def batch_run_metrics_global(
        self,
        sample_frac=0.20,
        max_images=10,
        seed=0,
        edge_grid=None,
        g_variants=None,
        cpu_max_workers=4,
        apply_to_sample=False,
        edges_only=False,
        edge_parallel_workers=None,
    ):
        """
        GLOBAL METRICS DRIVER

        PHASE A1: Edge sweep → global_best_edge
        PHASE A2: (optional) RS3 midline calibration → global_best_rs3
        PHASE B: Apply to all images

        NEW BEHAVIOR:
        • No per-image RS3 fallback.
        • If global RS3 fails → RS3 completely disabled for batch.
        • Pipeline continues safely using only edge tracking + manual midlines.
        """
        import os, json, random, time
        import numpy as np, pandas as pd
        from helpers import metrics
        from helpers.variant_optimizer import (
            optimize_across_dataset,
            apply_family_to_image,
        )

        # ------------------------------------------------------------------
        # Helper functions
        # ------------------------------------------------------------------
        if not getattr(self, "image_names", []):
            print("[global-metrics] no images loaded")
            return

        def _ann_path(idx):
            img_path = self.image_names[idx]
            base = os.path.splitext(os.path.basename(img_path))[0]
            return os.path.join(self.save_folder, f"{base}.json")

        def _has_manual_midlines(idx):
            path = _ann_path(idx)
            if not os.path.exists(path):
                return False
            if metrics._json_has_manual_midlines(path):
                return True
            # Fallback: full load
            orig = getattr(self, "n", 0)
            try:
                self.n = idx
                self.change_image()
                ann = (self.annotation or {}).get("annotations", {}) or {}
                atomic = ann.get("atomic_cracks", {}) or {}
                for cr in atomic.values():
                    src = (cr.get("source") or "").lower()
                    if src.startswith("auto") or src == "combined":
                        continue
                    mid = cr.get("midline", [])
                    if isinstance(mid, list) and len(mid) >= 2:
                        return True
                return False
            except Exception:
                return False
            finally:
                try:
                    self.n = orig
                    self.change_image()
                except Exception:
                    pass

        # ------------------------------------------------------------------
        # Build calibration set
        # ------------------------------------------------------------------
        rng = random.Random(seed)
        idxs_all = list(range(len(self.image_names)))
        eligible = [i for i in idxs_all if _has_manual_midlines(i)]

        if not eligible:
            print("[global-metrics] ❌ No images with manual midlines. Aborting.")
            if idxs_all:
                self.n = 0
                self.change_image()
            return

        rng.shuffle(eligible)
        k = max(1, int(len(eligible) * sample_frac))
        idxs_sample = eligible[:min(k, max_images)]
        print(f"[global-metrics] calibration on {len(idxs_sample)} images")

        if edge_grid is None:
            edge_grid = {
                "window_half_size": [35, 45, 55],
                "mu": [0, 5],
                "l": [2, 5],
                "p": [6, 14],
            }

        orig_n = self.n
        summ_dir = os.path.join(self.save_folder, "metrics", "_summary")
        os.makedirs(summ_dir, exist_ok=True)

        # ============================================================
        # PHASE A1: EDGE SWEEP → global_best_edge
        # ============================================================
        tA1_start = time.perf_counter()
        sweep_rows = []

        try:
            for t, idx in enumerate(idxs_sample, 1):
                self.n = idx
                self.change_image()

                base = os.path.splitext(os.path.basename(self.name))[0]
                print(f"\n====== [calibrate-edges] {t}/{len(idxs_sample)}: {base} ======")

                ann = self.annotation.get("annotations", {}) or {}
                atomic = ann.get("atomic_cracks", {}) or {}

                for cid, cr in atomic.items():
                    src = (cr.get("source") or "").lower()
                    if src.startswith("auto") or src == "combined":
                        continue
                    man = metrics._finite_xy(cr.get("midline", []))
                    if len(man) < 2:
                        continue

                    df = self.sweep_edges_with_executor(
                        cid, grid=edge_grid, max_workers=cpu_max_workers
                    )
                    if df is None or df.empty:
                        continue

                    D = df.copy()
                    D["image"] = base
                    D["crack_id"] = cid
                    sweep_rows.append(D)

            if sweep_rows:
                df_all = pd.concat(sweep_rows, ignore_index=True)
                df_all.to_csv(os.path.join(summ_dir, "global_edge_sweep_all.csv"), index=False)

                param_cols = ["param_window_half_size", "param_mu", "param_l", "param_p"]
                keep = param_cols + ["chamfer_mean", "hausdorff", "coverage"]
                sub = df_all[[c for c in keep if c in df_all.columns]].dropna()

                g = (sub.groupby(param_cols, as_index=False)
                        .agg({"chamfer_mean":"mean","hausdorff":"mean","coverage":"mean"}))
                g = g.sort_values(["chamfer_mean","hausdorff","coverage"],
                                ascending=[True, True, False])

                best = g.iloc[0].to_dict()
                global_best_edge = {
                    "window_half_size": int(best["param_window_half_size"]),
                    "mu": float(best["param_mu"]),
                    "l":  int(best["param_l"]),
                    "p":  int(best["param_p"]),
                }
            else:
                print("[global-metrics] ⚠ No sweep rows — falling back to defaults.")
                global_best_edge = {"window_half_size": 45, "mu": 0.0, "l": 5, "p": 14}

            with open(os.path.join(summ_dir, "global_best_edge_params.json"), "w") as f:
                json.dump(global_best_edge, f)

        finally:
            self.n = orig_n
            self.change_image()

        tA1 = time.perf_counter() - tA1_start
        print(f"[global-metrics] ⏱ edge calibration: {tA1:.2f}s")

        # ============================================================
        # PHASE A2: RS3 MIDLINE CALIBRATION (OPTIONAL)
        # ============================================================
        global_best_rs3 = None
        tA2 = 0.0

        if not edges_only:
            tA2_start = time.perf_counter()
            packs_by_image = {}

            try:
                for t, idx in enumerate(idxs_sample, 1):
                    self.n = idx
                    self.change_image()
                    base = os.path.splitext(os.path.basename(self.name))[0]
                    print(f"\n====== [calibrate-RS3] {t}/{len(idxs_sample)}: {base} ======")

                    ann = self.annotation.get("annotations", {}) or {}
                    atomic = ann.get("atomic_cracks", {}) or {}

                    packs_for_img = {}
                    for cid, cr in atomic.items():
                        src = (cr.get("source") or "").lower()
                        if src.startswith("auto") or src == "combined":
                            continue
                        man = metrics._finite_xy(cr.get("midline", []))
                        if len(man) < 2:
                            continue

                        pack = self.generate_auto_variants_for_manual_parallel(
                            crack_id=cid,
                            g_variants=g_variants,
                            edge_params_fixed=global_best_edge,
                            cpu_max_workers=cpu_max_workers,
                            force_recompute=True,
                        )
                        if pack:
                            packs_for_img[cid] = pack

                    if packs_for_img:
                        packs_by_image[base] = packs_for_img

                if packs_by_image:
                    global_best_rs3 = optimize_across_dataset(
                        packs_by_image,
                        save_global_json=os.path.join(summ_dir, "global_best_rs3_family.json")
                    )
                    if global_best_rs3:
                        print(f"[global-metrics] ✅ global RS3 family: {global_best_rs3}")
                    else:
                        print("[global-metrics] ⚠ RS3 calibration failed — RS3 disabled.")
                else:
                    print("[global-metrics] ⚠ No RS3 packs — RS3 disabled.")

            finally:
                self.n = orig_n
                self.change_image()

            tA2 = time.perf_counter() - tA2_start
            print(f"[global-metrics] ⏱ RS3 calibration: {tA2:.2f}s")

        # RS3 availability flag
        rs3_enabled = (global_best_rs3 is not None) and (not edges_only)

        # ============================================================
        # PHASE B: APPLY
        # ============================================================
        print("[global-metrics] applying global parameters...")
        apply_idxs = idxs_sample if apply_to_sample else idxs_all

        tB_start = time.perf_counter()
        per_image_times = []

        try:
            for t, idx in enumerate(apply_idxs, 1):

                base = os.path.splitext(os.path.basename(self.image_names[idx]))[0]
                ann_path = _ann_path(idx)

                # ---- Skip invalid images ----
                if not os.path.exists(ann_path):
                    print(f"[apply] ⚠ Skipping {base} — no JSON.")
                    continue
                if not metrics._json_has_manual_midlines(ann_path):
                    print(f"[apply] ⚠ Skipping {base} — no manual midlines.")
                    continue

                img_dir = os.path.join(self.save_folder, "metrics", base)
                done_flag = os.path.join(img_dir, "DONE.ok")

                # ---- Skip already processed ----
                if os.path.exists(done_flag):
                    print(f"[apply] ✓ already done: {base}")
                    continue

                # Load image
                self.n = idx
                self.change_image()
                os.makedirs(img_dir, exist_ok=True)

                print(f"\n====== [apply] {t}/{len(apply_idxs)}: {base} ======")

                # Save edge params for reference
                with open(os.path.join(img_dir, "edge_params_used.json"), "w") as f:
                    json.dump(global_best_edge, f)

                ann = self.annotation.get("annotations", {}) or {}
                atomic = ann.get("atomic_cracks", {}) or {}
                if not atomic:
                    print(f"[apply] no cracks in {base}")
                    open(done_flag, "a").close()
                    continue

                # ---- Timers ----
                t_img_start = time.perf_counter()
                t_auto = 0.0
                t_metrics = 0.0
                t_edge_parallel = 0.0

                processed = []

                # ====================================================
                # MODE 1 — EDGE-ONLY
                # ====================================================
                if edges_only:
                    t_edge_parallel_start = time.perf_counter()
                    try:
                        _ = self.run_edge_tracking_parallel(
                            crack_ids=list(atomic.keys()),
                            cpu_max_workers=edge_parallel_workers,
                            edge_params_fixed=global_best_edge,
                        )
                        processed = list(atomic.keys())
                    except Exception as e:
                        print(f"[apply] edge-only parallel failed: {e}")
                    t_edge_parallel = time.perf_counter() - t_edge_parallel_start

                    # Mask + width metrics (manual → GT only)
                    t_metrics_start = time.perf_counter()
                    try:
                        self.compute_mask_and_width_metrics_for_image(
                            display=False,
                            export_supervision=True,
                        )
                    except Exception as e:
                        print(f"[apply] mask/width failed: {e}")
                    t_metrics = time.perf_counter() - t_metrics_start

                # ====================================================
                # MODE 2 — FULL RS3 (requires global_best_rs3)
                # ====================================================
                else:
                    rs3_available = (global_best_rs3 is not None)

                    # ---- Collect only manual cracks with midlines ----
                    valid_ids = []
                    for cid, cr in atomic.items():
                        src = (cr.get("source") or "").lower()
                        if src.startswith("auto") or src == "combined":
                            continue
                        mid = metrics._finite_xy(cr.get("midline", []))
                        if len(mid) >= 2:
                            valid_ids.append(cid)

                    auto_packs = {}

                    # ====================================================
                    # RUN RS3 AUTO VARIANTS (ONLY IF DATASET-LEVEL FAMILY EXISTS)
                    # ====================================================
                    if rs3_available and valid_ids:
                        t_auto_start = time.perf_counter()
                        for cid in valid_ids:
                            try:
                                pack = self.generate_auto_variants_for_manual_parallel(
                                    crack_id=cid,
                                    g_variants=g_variants,
                                    edge_params_fixed=global_best_edge,
                                    cpu_max_workers=cpu_max_workers,
                                    force_recompute=True,
                                )
                                if pack:
                                    auto_packs[cid] = pack
                                processed.append(cid)
                            except Exception as e:
                                print(f"[apply] RS3 variant fail cid={cid}: {e}")
                        t_auto = time.perf_counter() - t_auto_start

                        # ---- Apply global RS3 family to all packs of this image ----
                        try:
                            if auto_packs:
                                apply_family_to_image(
                                    global_best_rs3,
                                    auto_packs,
                                    base_name=base,
                                    save_folder=self.save_folder,
                                )
                        except Exception as e:
                            print(f"[apply] RS3 family apply fail on {base}: {e}")
                            rs3_available = False
                            auto_packs = {}

                    else:
                        print(f"[apply] ⚠ No global RS3 family — skipping auto midlines for {base}")
                        auto_packs = {}

                    # ---- Final mask + width metrics ----
                    t_metrics_start = time.perf_counter()
                    try:
                        self.compute_mask_and_width_metrics_for_image(
                            display=False,
                            export_supervision=True,
                        )
                    except Exception as e:
                        print(f"[apply] mask/width failed: {e}")
                    t_metrics = time.perf_counter() - t_metrics_start

                # ----------------------------------------------------
                # LOGGING + DONE FLAG
                # ----------------------------------------------------
                t_img = time.perf_counter() - t_img_start

                row = {
                    "image": base,
                    "timestamp": time.strftime("%Y-%m-%d %H:%M:%S"),
                    "total_image_s": round(t_img, 2),
                    "metrics_s": round(t_metrics, 2),
                    "auto_variants_s": round(t_auto, 2),
                    "mask_build_s": 0.0,   # (now merged inside compute_mask_and_width_metrics_for_image)
                    "supervision_s": 0.0,  # (supervision done inside metrics function)
                    "edge_parallel_s": round(t_edge_parallel, 2),
                    "mode": ("edges_only" if edges_only else "full"),
                }
                per_image_times.append(row)

                try:
                    with open(os.path.join(img_dir, "status.json"), "w") as f:
                        json.dump({
                            "image": base,
                            "processed_cracks": processed,
                            "mode": ("edges_only" if edges_only else "full"),
                            "edge_params_used": global_best_edge,
                            "rs3_available": rs3_available,
                        }, f)
                    open(done_flag, "a").close()
                except Exception as e:
                    print(f"[apply] could not write DONE: {e}")

            # ---- Write per-image runtime table ----
            if per_image_times:
                df_times = pd.DataFrame(per_image_times)
                df_times.to_csv(os.path.join(summ_dir, "global_per_image_runtime.csv"), index=False)

            # Final dataset-level summarization
            self.summarize_dataset_metrics()

            # ---- Aggregate per-image runtime logs ----
            logs = []
            for img in self.image_names:
                base = os.path.splitext(os.path.basename(img))[0]
                path = os.path.join(self.save_folder, "metrics", base, "runtime_log.csv")
                if os.path.exists(path):
                    df = pd.read_csv(path)
                    df["image"] = base
                    logs.append(df)
            if logs:
                DF = pd.concat(logs, ignore_index=True)
                DF.to_csv(os.path.join(summ_dir, "global_runtime.csv"), index=False)

        finally:
            self.n = orig_n
            self.change_image()

        # Final timing summary
        tB = time.perf_counter() - tB_start
        total = tA1 + tA2 + tB
        with open(os.path.join(summ_dir, "global_runtime_summary.txt"), "w") as f:
            f.write(f"Phase A1 (edge calibration): {tA1:.2f} s\n")
            f.write(f"Phase A2 (RS3 calibration): {tA2:.2f} s\n")
            f.write(f"Phase B (application): {tB:.2f} s\n")
            f.write(f"Total runtime: {total:.2f} s\n")
            f.write(f"Mode: {'edges_only' if edges_only else 'full'}\n")
            f.write(f"Timestamp: {time.strftime('%Y-%m-%d %H:%M:%S')}\n")

        print(f"[global-metrics] ⏱ total runtime = {total:.2f}s (A1={tA1:.2f}, A2={tA2:.2f}, B={tB:.2f})")

    def export_training_supervision_for_image(self, cache_key=None, normal_half_span=32.0, step=0.5):
        """
        Export per-crack supervision artifacts for training/analysis.

        For each *manual* atomic crack:
        - manual_midline.csv
        - manual_mask.png (single-crack GT mask)
        - manual_gt_width_samples.csv (widths from GT mask along manual midline normals)
        - auto_best_midline.csv        (if best variant exists)
        - auto_best_normals_edge1.csv, auto_best_normals_edge2.csv (if present)
        - auto_best_params.json
        - auto_best_width_samples.csv  (if both auto edges present)

        All files saved under: metrics/<image>/supervision/cid<id>/
        """
        import os, json
        import numpy as np
        import pandas as pd
        import cv2
        

        def _ensure_dir(p):
            os.makedirs(p, exist_ok=True); return p

        def _resample_polyline(xy, step=1.0):
            xy = np.asarray(xy, float)
            if len(xy) < 2: return xy
            d = np.sqrt(((xy[1:] - xy[:-1])**2).sum(1))
            s = np.concatenate([[0.0], np.cumsum(d)])
            L = s[-1]
            if L <= 1e-6: return xy
            n = max(2, int(np.ceil(L/step))+1)
            s_new = np.linspace(0, L, n)
            # linear interpolate
            x = np.interp(s_new, s, xy[:,0])
            y = np.interp(s_new, s, xy[:,1])
            return np.column_stack([x,y])

        def _bilinear_sample(img01, pts_xy):
            # img01: HxW float {0,1}; pts_xy: Nx2 (x,y) floats
            H, W = img01.shape
            x = pts_xy[:,0].clip(0, W-1)
            y = pts_xy[:,1].clip(0, H-1)
            x0 = np.floor(x).astype(int); x1 = np.minimum(x0+1, W-1)
            y0 = np.floor(y).astype(int); y1 = np.minimum(y0+1, H-1)
            fx = x - x0; fy = y - y0
            Ia = img01[y0, x0]
            Ib = img01[y0, x1]
            Ic = img01[y1, x0]
            Id = img01[y1, x1]
            return (Ia*(1-fx)*(1-fy) + Ib*fx*(1-fy) + Ic*(1-fx)*fy + Id*fx*fy)

        def _edges_from_mask_along_normals(mid_xy, mask_bin, half_span=32.0, ds=0.5):
            # Returns DataFrame with per-sample mid/edge coords + width (px).
            xy = _resample_polyline(mid_xy, step=1.0)
            if len(xy) < 2: return pd.DataFrame()
            # tangents
            v = np.gradient(xy, axis=0)
            nrm = np.stack([-v[:,1], v[:,0]], axis=1)
            nrm_len = np.linalg.norm(nrm, axis=1, keepdims=True) + 1e-9
            n = nrm / nrm_len

            ts = np.arange(-half_span, half_span+1e-6, ds)  # sample offsets
            rows = []
            for i, p in enumerate(xy):
                line = p[None,:] + ts[:,None]*n[i:i+1,:]     # (T,2)
                vals = _bilinear_sample(mask_bin.astype(float), line)
                # pick leftmost ≥0.5 and rightmost ≥0.5 indices
                on = np.where(vals >= 0.5)[0]
                if len(on) == 0:
                    rows.append([i, p[0], p[1], np.nan, np.nan, np.nan, np.nan, np.nan])
                    continue
                il, ir = on[0], on[-1]
                xl, yl = line[il]
                xr, yr = line[ir]
                width = np.hypot(xr - xl, yr - yl)
                rows.append([i, p[0], p[1], xl, yl, xr, yr, width])

            return pd.DataFrame(rows, columns=[
                "sample_idx","mid_x","mid_y","edgeL_x","edgeL_y","edgeR_x","edgeR_y","width_px"
            ])

        if getattr(self, "current_mask", None) is None:
            print("[supervision] no GT mask loaded for this image"); 
            return

        base_name = os.path.splitext(os.path.basename(self.name))[0]
        image_dir = os.path.join(self.save_folder, "metrics", base_name)
        sup_root  = _ensure_dir(os.path.join(image_dir, "supervision"))

        H, W = self.original_image.shape[:2]
        mask_bin = (self.current_mask > 0).astype(np.uint8)

        ann = self.annotation.get("annotations", {}) or {}
        atomic = ann.get("atomic_cracks", {}) or {}
        cache_key = cache_key or metrics._auto_cache_key(self)

        for cid, crack in atomic.items():
            src = (crack.get("source") or "").lower()
            if src.startswith("auto") or src == "combined":
                continue

            man_xy = metrics._finite_xy(crack.get("midline", []))
            if len(man_xy) < 2:
                continue

            # paths
            out_dir = _ensure_dir(os.path.join(sup_root, f"cid{cid}"))

            # ---- Manual GT: midline + single-crack mask + width samples from mask
            pd.DataFrame(man_xy, columns=["x","y"]).to_csv(
                os.path.join(out_dir, "manual_midline.csv"), index=False
            )

            m_manual = metrics._reconstruct_full_mask(crack, H, W)
            cv2.imwrite(os.path.join(out_dir, "manual_mask.png"),
                        (m_manual>0).astype(np.uint8)*255)

            try:
                df_gt = _edges_from_mask_along_normals(
                    mid_xy=man_xy, mask_bin=mask_bin, half_span=normal_half_span, ds=step
                )
                if not df_gt.empty:
                    df_gt.to_csv(os.path.join(out_dir, "manual_gt_width_samples.csv"), index=False)
            except Exception as e:
                print(f"[supervision] GT widths failed for cid={cid}: {e}")

            # ---- Auto best variant artifacts (if exist)
            pack = crack.get("variants", {}).get("auto", {}).get(cache_key)
            if pack:
                bid = pack.get("best_variant_id")
                if bid is not None:
                    best = pack["variants"].get(f"v{bid}", {})

                    # midline
                    auto_xy = np.asarray(best.get("midline", []), dtype=float)
                    if auto_xy.size >= 4:
                        pd.DataFrame(auto_xy, columns=["x","y"]).to_csv(
                            os.path.join(out_dir, "auto_best_midline.csv"), index=False
                        )

                    # params
                    params = best.get("params", {})
                    try:
                        with open(os.path.join(out_dir, "auto_best_params.json"), "w") as f:
                            json.dump(params, f)
                    except Exception as e:
                        print(f"[supervision] write params failed for cid={cid}: {e}")

                    # normals/edge points (if edge worker provided them)
                    ne = best.get("normal_edge_points_full") or best.get("normal_edge_points")
                    if isinstance(ne, dict):
                        e1 = np.asarray(ne.get("edge1", []), float)
                        e2 = np.asarray(ne.get("edge2", []), float)
                        if e1.size >= 4:
                            pd.DataFrame(e1, columns=["x","y"]).to_csv(
                                os.path.join(out_dir, "auto_best_normals_edge1.csv"), index=False
                            )
                        if e2.size >= 4:
                            pd.DataFrame(e2, columns=["x","y"]).to_csv(
                                os.path.join(out_dir, "auto_best_normals_edge2.csv"), index=False
                            )
                        # If both edges present and aligned by index, dump per-sample widths
                        try:
                            if e1.size >= 4 and e2.size >= 4:
                                n = min(len(e1), len(e2))
                                w = np.hypot(e1[:n,0]-e2[:n,0], e1[:n,1]-e2[:n,1])
                                df_auto_w = pd.DataFrame({
                                    "idx": np.arange(n),
                                    "edge1_x": e1[:n,0], "edge1_y": e1[:n,1],
                                    "edge2_x": e2[:n,0], "edge2_y": e2[:n,1],
                                    "width_px": w
                                })
                                df_auto_w.to_csv(os.path.join(out_dir, "auto_best_width_samples.csv"), index=False)
                        except Exception as e:
                            print(f"[supervision] auto width export failed for cid={cid}: {e}")


    '''def run_midline_and_mask_metrics(self, tau_px=3.0, crack_id=None, display=True, do_param_sweep=True):
        """
        Wrapper for single-image metrics with timing logs.
        Delegates to run_metrics_on_current_image_quick(), then writes midline_metrics.csv
        and logs per-phase runtimes.
        """
        import os, numpy as np, pandas as pd, time

        # --- guard against running without an image loaded ---
        if not getattr(self, "name", None):
            print("[metrics] ⚠ no image loaded — aborting metrics run.")
            return

        base_name = os.path.splitext(os.path.basename(self.name))[0]
        image_dir = os.path.join(self.save_folder, "metrics", base_name)
        os.makedirs(image_dir, exist_ok=True)

        t_total_start = time.perf_counter()

        # 1) run new quick pipeline
        t_phase_start = time.perf_counter()
        _ = self.run_metrics_on_current_image_quick(
            edge_grid=None,
            g_variants=None,
            cpu_max_workers=8,
            do_edge_calibrate=bool(do_param_sweep)
        )
        t_phase_auto = time.perf_counter() - t_phase_start

        # 2) re-materialize midline_metrics.csv
        t_phase_start = time.perf_counter()
        ann = self.annotation.get("annotations", {}) or {}
        atomic = ann.get("atomic_cracks", {}) or {}

        rows = []
        cache_key = metrics._auto_cache_key(self)
        for cid, crack in atomic.items():
            if (crack_id is not None) and (cid != str(crack_id)):
                continue
            src = (crack.get("source") or "").lower()
            if src.startswith("auto") or src == "combined":
                continue

            man_xy = metrics._finite_xy(crack.get("midline", []))
            if len(man_xy) < 2:
                continue

            pack = crack.get("variants", {}).get("auto", {}).get(cache_key)
            if not pack:
                continue
            bid = pack.get("best_variant_id")
            if bid is None:
                continue
            best = pack["variants"].get(f"v{bid}", {})
            auto_xy = metrics._finite_xy(best.get("midline", []))
            if len(auto_xy) < 2:
                continue

            mm = metrics.compute_midline_metrics(auto_xy, man_xy, tau=tau_px)
            mm.update({"image": base_name, "crack_id": cid, "best_variant_id": bid})
            rows.append(mm)

        if rows:
            pd.DataFrame(rows).to_csv(os.path.join(image_dir, "midline_metrics.csv"), index=False)

        t_phase_midline = time.perf_counter() - t_phase_start

        # 3) Mask/width metrics
        t_phase_start = time.perf_counter()
        if display:
            try:
                self.compute_mask_and_width_metrics_for_image(display=True)
            except Exception as e:
                print(f"[metrics] mask/width stage failed: {e}")
        else:
            try:
                self.compute_mask_and_width_metrics_for_image(display=False)
            except Exception as e:
                print(f"[metrics] mask/width stage failed: {e}")
        t_phase_maskwidth = time.perf_counter() - t_phase_start

        # --- Total runtime ---
        elapsed_total = time.perf_counter() - t_total_start

        # --- Write timing log ---
        timing_log = os.path.join(image_dir, "runtime_log.csv")
        row = {
            "image": base_name,
            "phase_auto_variants_s": round(t_phase_auto, 2),
            "phase_midline_metrics_s": round(t_phase_midline, 2),
            "phase_mask_width_s": round(t_phase_maskwidth, 2),
            "total_runtime_s": round(elapsed_total, 2),
            "timestamp": time.strftime("%Y-%m-%d %H:%M:%S"),
        }

        import pandas as pd
        try:
            if os.path.exists(timing_log):
                df = pd.read_csv(timing_log)
                df = pd.concat([df, pd.DataFrame([row])], ignore_index=True)
            else:
                df = pd.DataFrame([row])
            df.to_csv(timing_log, index=False)
        except Exception as e:
            print(f"[metrics] ⚠ failed to write runtime_log.csv: {e}")

        print(f"[metrics] ⏱ total runtime = {elapsed_total:.2f} sec "
            f"(auto={t_phase_auto:.2f}s, midline={t_phase_midline:.2f}s, mask/width={t_phase_maskwidth:.2f}s)")'''
                
    def dump_global_midline_and_mask_overlays(self, thickness_px=3):
        """
        Reconstruct full-image debug masks and overlays (strict, edges-only):
        - GT mask = self.current_mask (if loaded)
        - midlines = from crack['midline']
        - edge mask = polygon filled from geodesic_edges only
        Writes under Outputs/metrics/<base>/.
        """
        import os, json, numpy as np, cv2
        from helpers.metrics import reconstruct_manual_mask_from_edges, merged_metric_atomic

        base_name = os.path.splitext(os.path.basename(self.name))[0]
        image_dir = os.path.join(self.save_folder, "metrics", base_name)
        os.makedirs(image_dir, exist_ok=True)

        H, W = self.original_image.shape[:2]

        # --- Authoring + merged (with per-cid edges) ---
        authoring_atomic = (self.annotation or {}).get("annotations", {}).get("atomic_cracks", {}) or {}
        atomic = merged_metric_atomic(authoring_atomic, self.save_folder, base_name)
        def _is_manual(cr):
            src = (cr.get("source") or "").lower()
            # adjust this tuple if you have other manual-like sources
            return src in ("manual", "manual_poly")

        atomic_manual = {cid: cr for cid, cr in atomic.items() if _is_manual(cr)}
        print(f"[DEBUG METRICS] using {len(atomic_manual)} manual cracks for mask/width metrics")
        atomic = atomic_manual

        print(f"[DBG global] reconstructing strict overlays for {len(atomic)} cracks (H={H}, W={W})")

        # --- Initialize canvases ---
        gt_mask      = np.zeros((H, W), np.uint8)
        midline_mask = np.zeros((H, W), np.uint8)
        edge_mask    = np.zeros((H, W), np.uint8)

        # --- Load ground truth mask if present ---
        if getattr(self, "current_mask", None) is not None:
            gt_mask = ((self.current_mask > 0).astype(np.uint8) * 255)
            print(f"[DBG global] GT nnz={int(np.count_nonzero(gt_mask))}")
        else:
            print(f"[DBG global] ⚠ no self.current_mask, GT empty")

        # --- Draw midlines + edges ---
        def _draw_midline(mask, pts, thick):
            arr = np.asarray(pts, float)
            arr = arr[np.isfinite(arr).all(axis=1)]
            if len(arr) >= 2:
                cv2.polylines(mask, [arr.astype(np.int32)], False, 255, thick, lineType=cv2.LINE_AA)

        for cid, crack in atomic.items():
            src = (crack.get("source") or "").lower()
            ml  = crack.get("midline", []) or crack.get("midline_segments", [])
            ge  = crack.get("geodesic_edges", {})
            print(f"  cid={str(cid):>3s} src={src:12s} edge_keys={list(ge.keys()) if ge else []}")

            # midlines
            try:
                if ml:
                    if isinstance(ml[0], (list, tuple)) and isinstance(ml[0][0], (list, tuple)):
                        for seg in ml:
                            _draw_midline(midline_mask, seg, thickness_px)
                    else:
                        _draw_midline(midline_mask, ml, thickness_px)
            except Exception as e:
                print(f"    [midline] fail: {e}")

            # strictly edge polygon fill
            try:
                m_edge = reconstruct_manual_mask_from_edges(crack, H, W)
                edge_mask |= (m_edge > 0).astype(np.uint8) * 255
            except Exception as e:
                print(f"    [edges] fail: {e}")

        # --- Save binary masks ---
        cv2.imwrite(os.path.join(image_dir, "global_gt_mask.png"), gt_mask)
        cv2.imwrite(os.path.join(image_dir, "global_midlines_mask.png"), midline_mask)
        cv2.imwrite(os.path.join(image_dir, "global_edge_mask.png"), edge_mask)

        # --- Overlays ---
        rgb = self.original_image
        if rgb.ndim == 2:
            rgb = cv2.cvtColor(rgb, cv2.COLOR_GRAY2BGR)

        def _colorize(mask, bgr):
            c = np.zeros_like(rgb)
            c[mask > 0] = bgr
            return c

        gt_rgb   = _colorize(gt_mask,   (0, 0, 255))     # red
        mid_rgb  = _colorize(midline_mask, (255, 255, 255)) # white
        edge_rgb = _colorize(edge_mask, (0, 255, 0))     # green

        ov_mid  = cv2.addWeighted(rgb, 0.65, gt_rgb, 0.45, 0)
        ov_mid  = cv2.addWeighted(ov_mid, 1.00, mid_rgb, 0.70, 0)
        ov_edge = cv2.addWeighted(rgb, 0.65, gt_rgb, 0.45, 0)
        ov_edge = cv2.addWeighted(ov_edge, 1.00, edge_rgb, 0.70, 0)

        cv2.imwrite(os.path.join(image_dir, "overlay_gt_vs_midlines.png"), ov_mid)
        cv2.imwrite(os.path.join(image_dir, "overlay_gt_vs_edge_masks.png"), ov_edge)

        print(f"[DBG global] nnz(gt)={int(np.count_nonzero(gt_mask))} "
            f"nnz(mid)={int(np.count_nonzero(midline_mask))} "
            f"nnz(edge)={int(np.count_nonzero(edge_mask))}")
        print(f"[DBG global] ✅ wrote overlays + masks → {image_dir}")

    # ===============================================================
    # === Global debug toggle (place near imports in your file) ===
    # ===============================================================

    # ===============================================================
    # === Compute mask & width metrics (light / full aware) ===
    # ===============================================================
    def export_midline_edge_metrics(self, base_name, metrics_dir):
        import os, json, numpy as np, pandas as pd, matplotlib.pyplot as plt

        rows = []
        atomic = self._metric_atomic() or {}
        combined = self._metric_combined() or {}
        members_in_combined = {str(m) for cmb in combined.values() for m in (cmb.get("members", []) or [])}

        # only atomics NOT in a combined (to avoid double counting)
        for cid in sorted(atomic.keys(), key=lambda z: int(z)):
            scid = str(cid)
            if scid in members_in_combined:
                continue
            #path = os.path.join(self.save_folder, "metrics", base_name, f"cid{scid}.json")
            path = metric_atomic_path_for(self.save_folder, base_name, scid)
            if not os.path.exists(path): 
                continue
            try:
                with open(path, "r", encoding="utf-8") as f:
                    data = json.load(f)
            except Exception:
                continue
            if not isinstance(data, dict): 
                continue

            row = {
                "image": base_name,
                "crack_type": "atomic",
                "crack_id": scid,
                "win": data.get("window_half_size"),
                "mu": data.get("mu"),
                "l": data.get("l"),
                "p": data.get("p"),
                "chamfer_mean": data.get("chamfer_mean"),
                "hausdorff": data.get("hausdorff"),
                "angle_err_deg": data.get("angle_err_deg"),
                "coverage": data.get("coverage"),
                "directional_bias": data.get("directional_bias"),
                "curvature_rms_ratio": data.get("curvature_rms_ratio"),
                "local_thickness_corr": data.get("local_thickness_corr"),
            }
            rows.append(row)

        if not rows:
            return

        df = pd.DataFrame(rows)
        out_csv = os.path.join(metrics_dir, f"{base_name}_midline_edge_metrics.csv")
        df.to_csv(out_csv, index=False)

        # quick summary by crack_type
        g = df.groupby("crack_type").agg(["mean", "std"])
        out_sum = os.path.join(metrics_dir, f"{base_name}_midline_edge_metrics_summary.csv")
        g.to_csv(out_sum)

        # tiny bar chart of a few key metrics (mean ± std)
        try:
            metrics_pick = ["chamfer_mean", "hausdorff", "angle_err_deg", "coverage"]
            means = df[metrics_pick].mean()
            stds  = df[metrics_pick].std()
            plt.figure(figsize=(7,4), dpi=200)
            x = np.arange(len(metrics_pick))
            plt.bar(x, means.values, yerr=stds.values)
            plt.xticks(x, metrics_pick, rotation=15)
            plt.tight_layout()
            plt.savefig(os.path.join(metrics_dir, f"{base_name}_midline_edge_metrics_barchart.png"), dpi=200)
            plt.close()
        except Exception:
            pass
    
